import { useEffect, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { Building2, Car, Save, UserRound } from 'lucide-react';
import { toast } from 'sonner';
import { ClaimDataSection } from '@/modules/cases/components/claim-data-section';
import { InsuranceDataSection } from '@/modules/cases/components/insurance-data-section';
import { DocumentsSection } from '@/modules/cases/components/documents-section';
import { LawyerThirdPartyIncidentSection } from '@/modules/cases/components/lawyer-third-party-incident-section';
import { ProcedureSection } from '@/modules/cases/components/procedure-section';
import { TaskAgenda } from '@/modules/cases/components/task-agenda';
import { addCasePerson, deleteCasePerson, getCasePersons, getThirdParty, getThirdPartyWorkshop, saveThirdParty, saveThirdPartyWorkshop, updateCasePerson } from '@/modules/cases/api/third-party-api';
import { createPerson, createVehicle, listInsuranceCompanies, listInsuranceCompanyContacts, searchPersons, searchVehicles } from '@/modules/cases/api/new-case-api';
import { requestJson } from '@/shared/api/http-client';
import { Button } from '@/shared/ui/button';
import { Dialog } from '@/shared/ui/dialog';
import { Input } from '@/shared/ui/input';
import { Textarea } from '@/shared/ui/textarea';

const Field = ({ label, children, className = '' }) => <label className={`block min-w-0 text-[11px] font-semibold uppercase tracking-[0.14em] text-muted-foreground ${className}`}><span className="mb-1 block">{label}</span>{children}</label>;
const emptyWorkshop = { thirdPartyCompanyId: '', claimReference: '', thirdPartyVehicleId: '', driverPersonId: '', processorPersonId: '', inspectorPersonId: '' };
const emptyVehicle = { search: '', brandText: '', modelText: '', plate: '' };
const emptyContact = { name: '', email: '', phone: '' };
const personName = (person) => person?.nombreMostrar || [person?.nombre, person?.apellido].filter(Boolean).join(' ');

export const ThirdPartyWorkshopEditor = ({ caseId, caseDetail, budget, lawyerManaged = false }) => {
  if (lawyerManaged) return <div className="mt-5 space-y-5 pb-20">
    <InsuranceDataSection caseId={caseId} caseDetail={caseDetail} />
    <LawyerThirdPartyIncidentSection caseId={caseId} />
    <DocumentsSection caseId={caseId} moduleCode="GESTION_TRAMITE" includeHistorical title="Documentación del trámite" showCompleteAction={false} />
    <ProcedureSection caseId={caseId} budget={budget} thirdPartyWorkshop />
    <TaskAgenda caseId={caseId} organizationId={caseDetail?.organizationId} branchId={caseDetail?.branchId} />
  </div>;

  return <div className="mt-5 space-y-5 pb-20"><GeneralDataSection caseId={caseId} /><InsuranceDataSection caseId={caseId} /><ThirdPartyWorkshopIncidentSection caseId={caseId} /><DocumentsSection caseId={caseId} moduleCode="GESTION_TRAMITE" originCode="GESTION_TRAMITE" includeHistorical={false} title="Documentación" showCompleteAction showAllCategories editableMetadata /><ProcedureSection caseId={caseId} thirdPartyWorkshop hideGeneralData /><CoverageSection caseId={caseId} caseDetail={caseDetail} budget={budget} /></div>;
};

const prescriptionFromPresentation = (presentedAt) => {
  if (!presentedAt) return '';
  const date = new Date(`${presentedAt}T00:00:00`);
  date.setFullYear(date.getFullYear() + 3);
  return date.toISOString().slice(0, 10);
};

const GeneralDataSection = ({ caseId }) => {
  const queryClient = useQueryClient();
  const incidentQuery = useQuery({ queryKey: ['cases', String(caseId), 'incident'], queryFn: () => requestJson(`/cases/${caseId}/incident`) });
  const processingQuery = useQuery({ queryKey: ['cases', String(caseId), 'insurance-processing'], queryFn: () => requestJson(`/cases/${caseId}/insurance-processing`) });
  const [incidentDate, setIncidentDate] = useState('');
  const [presentedAt, setPresentedAt] = useState('');
  const [opinionCode, setOpinionCode] = useState('APROBADO');
  useEffect(() => { setIncidentDate(incidentQuery.data?.incidentDate ?? ''); }, [incidentQuery.data]);
  useEffect(() => { setPresentedAt(processingQuery.data?.presentedAt ?? ''); setOpinionCode(processingQuery.data?.opinionCode ?? 'APROBADO'); }, [processingQuery.data]);
  const saveMutation = useMutation({
    mutationFn: async () => {
      await requestJson(`/cases/${caseId}/incident`, { method: 'PUT', body: JSON.stringify({ incidentDate: incidentDate || null, incidentTime: incidentQuery.data?.incidentTime ?? null, location: incidentQuery.data?.location ?? null, dynamics: incidentQuery.data?.dynamics ?? null, observations: incidentQuery.data?.observations ?? null }) });
      return requestJson(`/cases/${caseId}/insurance-processing`, { method: 'PATCH', body: JSON.stringify({ expectedVersion: processingQuery.data?.version ?? 0, presentedAt: presentedAt || null, opinionCode }) });
    },
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'incident'] }),
        queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'insurance-processing'] }),
        queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'workspace'] }),
      ]);
      toast.success('Datos generales guardados.');
    },
    onError: (error) => toast.error(error.message || 'No se pudieron guardar los datos generales.'),
  });
  const prescriptionDate = presentedAt ? prescriptionFromPresentation(presentedAt) : '';
  const daysInProcess = incidentQuery.data?.daysInProcess;
  return <section className="rounded-3xl border border-border/70 bg-card p-5"><div className="flex items-center justify-between gap-3"><div><h4 className="text-sm font-semibold">Datos generales</h4><p className="text-xs text-muted-foreground">La prescripción y los días tramitando los calcula el sistema.</p></div><Button size="sm" onClick={() => saveMutation.mutate()} disabled={saveMutation.isPending}><Save className="mr-1.5 h-3.5 w-3.5" />Guardar</Button></div><div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3"><Field label="Fecha del siniestro"><Input aria-label="Fecha del siniestro" type="date" value={incidentDate} onChange={(event) => setIncidentDate(event.target.value)} /></Field><Field label="Fecha presentado"><Input aria-label="Fecha presentado" type="date" value={presentedAt} onChange={(event) => setPresentedAt(event.target.value)} /></Field><CalculatedField label="Prescripción del trámite" value={prescriptionDate} fallback="Ingresá Fecha presentado" /><CalculatedField label="Días tramitando" value={daysInProcess ?? ''} fallback="Ingresá Fecha presentado" /><Field label="Dictamen"><select aria-label="Dictamen" value={opinionCode} onChange={(event) => setOpinionCode(event.target.value)} className="h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="APROBADO">A favor</option><option value="RECHAZADO">En contra</option></select></Field></div>{!presentedAt ? <p className="mt-3 text-xs text-muted-foreground">Ingresá Fecha presentado para calcular la prescripción y los días tramitando.</p> : null}</section>;
};

const emptyInsuranceContact = { personId: '', creating: false, name: '', lastName: '', email: '', phone: '', person: null };
const contactForm = (contact) => contact ? { personId: String(contact.personId ?? ''), creating: false, name: contact.name ?? '', lastName: '', email: contact.email ?? '', phone: contact.phone ?? '', person: null } : emptyInsuranceContact;

const InsuranceContactField = ({ label, companyId, roleCode, value, onChange }) => {
  const contactsQuery = useQuery({ queryKey: ['insurance', 'companies', companyId, 'contacts'], queryFn: () => listInsuranceCompanyContacts(companyId), enabled: Boolean(companyId) });
  const personQuery = useQuery({ queryKey: ['persons', value.personId], queryFn: () => requestJson(`/persons/${value.personId}`), enabled: Boolean(value.personId) });
  const contacts = (contactsQuery.data ?? []).filter((contact) => contact.contactRoleCode === roleCode);
  useEffect(() => {
    if (!personQuery.data || value.creating) return;
    onChange((current) => ({ ...current, name: personQuery.data.nombre ?? '', lastName: personQuery.data.apellido ?? '', email: personQuery.data.emailPrincipal ?? '', phone: personQuery.data.telefonoPrincipal ?? '', person: personQuery.data }));
  }, [personQuery.data, value.creating, value.personId]);
  if (!companyId) return <Field label={label}><p className="py-2 text-sm font-normal normal-case text-muted-foreground">Seleccioná la compañía del tercero para elegir un contacto.</p></Field>;
  return <Field label={label}><select aria-label={label} value={value.creating ? '__new' : value.personId} onChange={(event) => onChange(event.target.value === '__new' ? { ...emptyInsuranceContact, creating: true } : { ...emptyInsuranceContact, personId: event.target.value })} className="h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Seleccionar...</option>{contacts.map((contact) => <option key={contact.id} value={contact.personId}>{contact.personName}</option>)}<option value="__new">Crear contacto...</option></select>{value.creating || value.personId ? <div className="mt-2 grid gap-2 md:grid-cols-2"><Input aria-label={`Nombre ${label}`} value={value.name} onChange={(event) => onChange((current) => ({ ...current, name: event.target.value }))} placeholder="Nombre" /><Input aria-label={`Apellido ${label}`} value={value.lastName} onChange={(event) => onChange((current) => ({ ...current, lastName: event.target.value }))} placeholder="Apellido" /><Input aria-label={`Correo ${label}`} type="email" value={value.email} onChange={(event) => onChange((current) => ({ ...current, email: event.target.value }))} placeholder="correo@compania.com" /><Input aria-label={`Teléfono ${label}`} value={value.phone} onChange={(event) => onChange((current) => ({ ...current, phone: event.target.value }))} placeholder="Teléfono" /></div> : null}</Field>;
};

const InsuranceDataSection = ({ caseId }) => {
  const queryClient = useQueryClient();
  const insuranceQuery = useQuery({ queryKey: ['cases', String(caseId), 'insurance'], queryFn: () => requestJson(`/cases/${caseId}/insurance`) });
  const workshopQuery = useQuery({ queryKey: ['cases', String(caseId), 'third-party-workshop'], queryFn: () => getThirdPartyWorkshop(caseId) });
  const companiesQuery = useQuery({ queryKey: ['insurance', 'companies'], queryFn: listInsuranceCompanies });
  const [insurance, setInsurance] = useState({ companyId: '', claimNumber: '' });
  const [workshop, setWorkshop] = useState({ companyId: '', claimReference: '', processor: emptyInsuranceContact, inspector: emptyInsuranceContact });
  useEffect(() => { setInsurance({ companyId: String(insuranceQuery.data?.insuranceCompanyId ?? ''), claimNumber: insuranceQuery.data?.claimNumber ?? '' }); }, [insuranceQuery.data]);
  useEffect(() => { const data = workshopQuery.data; if (!data) return; setWorkshop({ companyId: String(data.thirdPartyCompanyId ?? ''), claimReference: data.claimReference ?? '', processor: contactForm(data.processor), inspector: contactForm(data.inspector) }); }, [workshopQuery.data]);
  const updateExistingContact = async (contact) => {
    if (!contact.personId || !contact.person) return;
    await requestJson(`/persons/${contact.personId}`, { method: 'PUT', body: JSON.stringify({ tipoPersona: contact.person.tipoPersona ?? 'fisica', nombre: contact.name || null, apellido: contact.lastName || null, razonSocial: contact.person.razonSocial ?? null, tipoDocumentoCodigo: contact.person.tipoDocumentoCodigo ?? null, numeroDocumento: contact.person.numeroDocumento ?? null, cuitCuil: contact.person.cuitCuil ?? null, fechaNacimiento: contact.person.fechaNacimiento ?? null, telefonoPrincipal: contact.phone || null, emailPrincipal: contact.email || null, ocupacion: contact.person.ocupacion ?? null, observaciones: contact.person.observaciones ?? null, estadoCivilCodigo: contact.person.estadoCivilCodigo ?? null, activo: contact.person.activo ?? true }) });
  };
  const saveMutation = useMutation({ mutationFn: async () => {
    if (insurance.companyId) await requestJson(`/cases/${caseId}/insurance`, { method: 'PUT', body: JSON.stringify({ insuranceCompanyId: Number(insurance.companyId), policyNumber: insuranceQuery.data?.policyNumber ?? null, certificateNumber: insuranceQuery.data?.certificateNumber ?? null, coverageDetail: insuranceQuery.data?.coverageDetail ?? null, claimNumber: insurance.claimNumber || null, processorPersonId: insuranceQuery.data?.processorPersonId ?? null, inspectorPersonId: insuranceQuery.data?.inspectorPersonId ?? null }) });
    if (!workshop.companyId && (workshop.processor.personId || workshop.processor.creating || workshop.inspector.personId || workshop.inspector.creating)) throw new Error('Seleccioná la compañía del tercero antes de guardar sus contactos.');
    await Promise.all([updateExistingContact(workshop.processor), updateExistingContact(workshop.inspector)]);
    return saveThirdPartyWorkshop(caseId, { thirdPartyCompanyId: workshop.companyId ? Number(workshop.companyId) : null, claimReference: workshop.claimReference || null, thirdPartyVehicleId: workshopQuery.data?.thirdPartyVehicleId ?? null, driverPersonId: workshopQuery.data?.driverPersonId ?? null, processorPersonId: workshop.processor.personId ? Number(workshop.processor.personId) : null, newProcessor: workshop.processor.creating && workshop.processor.name.trim() ? { name: workshop.processor.name.trim(), lastName: workshop.processor.lastName.trim() || null, email: workshop.processor.email || null, phone: workshop.processor.phone || null } : null, inspectorPersonId: workshop.inspector.personId ? Number(workshop.inspector.personId) : null, newInspector: workshop.inspector.creating && workshop.inspector.name.trim() ? { name: workshop.inspector.name.trim(), lastName: workshop.inspector.lastName.trim() || null, email: workshop.inspector.email || null, phone: workshop.inspector.phone || null } : null });
  }, onSuccess: async (saved) => { queryClient.setQueryData(['cases', String(caseId), 'third-party-workshop'], saved); await Promise.all([queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'insurance'] }), queryClient.invalidateQueries({ queryKey: ['insurance', 'companies'] }), queryClient.invalidateQueries({ queryKey: ['insurance', 'companies', workshop.companyId, 'contacts'] })]); toast.success('Datos del seguro guardados.'); }, onError: (error) => toast.error(error.message || 'No se pudieron guardar los datos del seguro.') });
  return <section className="rounded-3xl border border-border/70 bg-card p-5"><div className="flex items-center justify-between gap-3"><div><h4 className="text-sm font-semibold">Datos del seguro</h4><p className="text-xs text-muted-foreground">Compañías, referencias y contactos reutilizables.</p></div><Button size="sm" onClick={() => saveMutation.mutate()} disabled={saveMutation.isPending}><Save className="mr-1.5 h-3.5 w-3.5" />Guardar</Button></div><div className="mt-4 grid gap-3 md:grid-cols-2"><Field label="Cía. aseguradora"><select aria-label="Cía. aseguradora" value={insurance.companyId} onChange={(event) => setInsurance((current) => ({ ...current, companyId: event.target.value }))} className="h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Seleccionar...</option>{(companiesQuery.data ?? []).map((company) => <option key={company.id} value={company.id}>{company.name}</option>)}</select></Field><Field label="Cía. del tercero"><select aria-label="Cía. del tercero" value={workshop.companyId} onChange={(event) => setWorkshop((current) => ({ ...current, companyId: event.target.value, processor: emptyInsuranceContact, inspector: emptyInsuranceContact }))} className="h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Seleccionar...</option>{(companiesQuery.data ?? []).map((company) => <option key={company.id} value={company.id}>{company.name}</option>)}</select></Field><Field label="N.º de siniestro"><Input aria-label="N.º de siniestro" value={insurance.claimNumber} onChange={(event) => setInsurance((current) => ({ ...current, claimNumber: event.target.value }))} /></Field><Field label="N.º de reclamo / referencia"><Input aria-label="N.º de reclamo / referencia" value={workshop.claimReference} onChange={(event) => setWorkshop((current) => ({ ...current, claimReference: event.target.value }))} /></Field><InsuranceContactField label="Tramitador/a" companyId={workshop.companyId} roleCode="TRAMITADOR" value={workshop.processor} onChange={(update) => setWorkshop((current) => ({ ...current, processor: typeof update === 'function' ? update(current.processor) : update }))} /><InsuranceContactField label="Inspector/a" companyId={workshop.companyId} roleCode="INSPECTOR" value={workshop.inspector} onChange={(update) => setWorkshop((current) => ({ ...current, inspector: typeof update === 'function' ? update(current.inspector) : update }))} /></div></section>;
};

const emptyPersonDetails = { personId: '', name: '', lastName: '', dni: '', address: '', ownership: '100' };
const addressText = (address) => [address?.calle, address?.numero, address?.piso && `Piso ${address.piso}`, address?.depto && `Dto. ${address.depto}`, address?.localidad, address?.provincia].filter(Boolean).join(', ');
const personPayload = (person, current = {}) => ({ tipoPersona: current.tipoPersona ?? 'fisica', nombre: person.name || null, apellido: person.lastName || null, razonSocial: current.razonSocial ?? null, tipoDocumentoCodigo: current.tipoDocumentoCodigo ?? 'DNI', numeroDocumento: person.dni || null, cuitCuil: current.cuitCuil ?? null, fechaNacimiento: current.fechaNacimiento ?? null, telefonoPrincipal: current.telefonoPrincipal ?? null, emailPrincipal: current.emailPrincipal ?? null, ocupacion: current.ocupacion ?? null, observaciones: current.observaciones ?? null, estadoCivilCodigo: current.estadoCivilCodigo ?? null, activo: current.activo ?? true });

const PersonSummaryFields = ({ prefix, value, onChange, allowOwnership = false }) => <div className="grid gap-2 md:grid-cols-2"><Input aria-label={`Nombre ${prefix}`} value={value.name} onChange={(event) => onChange((current) => ({ ...current, name: event.target.value }))} placeholder="Nombre" /><Input aria-label={`Apellido ${prefix}`} value={value.lastName} onChange={(event) => onChange((current) => ({ ...current, lastName: event.target.value }))} placeholder="Apellido" /><Input aria-label={`DNI ${prefix}`} value={value.dni} onChange={(event) => onChange((current) => ({ ...current, dni: event.target.value }))} placeholder="DNI" /><Input aria-label={`Domicilio ${prefix}`} value={value.address} onChange={(event) => onChange((current) => ({ ...current, address: event.target.value }))} placeholder="Domicilio" />{allowOwnership ? <Input aria-label={`Porcentaje ${prefix}`} type="number" min="1" max="100" value={value.ownership} onChange={(event) => onChange((current) => ({ ...current, ownership: event.target.value }))} /> : null}</div>;

const ThirdPartyWorkshopIncidentSection = ({ caseId }) => {
  const queryClient = useQueryClient();
  const incidentQuery = useQuery({ queryKey: ['cases', String(caseId), 'incident'], queryFn: () => requestJson(`/cases/${caseId}/incident`) });
  const workshopQuery = useQuery({ queryKey: ['cases', String(caseId), 'third-party-workshop'], queryFn: () => getThirdPartyWorkshop(caseId) });
  const personsQuery = useQuery({ queryKey: ['cases', String(caseId), 'persons'], queryFn: () => getCasePersons(caseId) });
  const vehicleId = workshopQuery.data?.thirdPartyVehicleId;
  const driverPersonId = workshopQuery.data?.driverPersonId;
  const vehicleQuery = useQuery({ queryKey: ['vehicles', vehicleId], queryFn: () => requestJson(`/vehicles/${vehicleId}`), enabled: Boolean(vehicleId) });
  const driverQuery = useQuery({ queryKey: ['persons', driverPersonId], queryFn: () => requestJson(`/persons/${driverPersonId}`), enabled: Boolean(driverPersonId) });
  const driverAddressesQuery = useQuery({ queryKey: ['persons', driverPersonId, 'addresses'], queryFn: () => requestJson(`/persons/${driverPersonId}/addresses`), enabled: Boolean(driverPersonId) });
  const [incident, setIncident] = useState({ location: '', incidentTime: '', dynamics: '', observations: '' });
  const [vehicle, setVehicle] = useState({ id: '', plate: '', brandText: '', modelText: '' });
  const [driver, setDriver] = useState(emptyPersonDetails);
  const [driverIsOwner, setDriverIsOwner] = useState(false);
  const [ownerDraft, setOwnerDraft] = useState(emptyPersonDetails);
  const [ownerSearch, setOwnerSearch] = useState('');
  const ownerSearchQuery = useQuery({ queryKey: ['persons', 'third-party-owner', ownerSearch], queryFn: () => searchPersons({ q: ownerSearch }), enabled: ownerSearch.trim().length >= 2 });
  const owners = (personsQuery.data ?? []).filter((person) => person.caseRoleCode === 'TITULAR' && Number(person.vehicleId) === Number(vehicleId));
  const ownershipTotal = owners.reduce((total, owner) => total + Number(owner.registryOwnershipPercentage ?? 0), 0);
  const remaining = Math.max(0, 100 - ownershipTotal);
  useEffect(() => { const data = incidentQuery.data; if (data) setIncident({ location: data.location ?? '', incidentTime: data.incidentTime ?? '', dynamics: data.dynamics ?? '', observations: data.observations ?? '' }); }, [incidentQuery.data]);
  useEffect(() => { const data = vehicleQuery.data; if (data?.id) setVehicle({ id: String(data.id), plate: data.plate ?? '', brandText: data.brandText ?? '', modelText: data.modelText ?? '' }); }, [vehicleQuery.data]);
  useEffect(() => { const person = driverQuery.data; if (person) setDriver((current) => ({ ...current, personId: String(person.id), name: person.nombre ?? '', lastName: person.apellido ?? '', dni: person.numeroDocumento ?? '', address: addressText((driverAddressesQuery.data ?? []).find((address) => address.principal) ?? driverAddressesQuery.data?.[0]) })); }, [driverQuery.data, driverAddressesQuery.data]);
  useEffect(() => { setDriverIsOwner(Boolean(driverPersonId && owners.some((owner) => String(owner.personId) === String(driverPersonId)))); }, [driverPersonId, personsQuery.data, vehicleId]);
  const savePerson = async (details, current = null) => {
    const saved = details.personId ? await requestJson(`/persons/${details.personId}`, { method: 'PUT', body: JSON.stringify(personPayload(details, current ?? {})) }) : await createPerson(personPayload(details));
    if (!details.personId && details.address.trim()) await requestJson(`/persons/${saved.id}/addresses`, { method: 'POST', body: JSON.stringify({ tipoDomicilioCodigo: 'PARTICULAR', calle: details.address.trim(), numero: null, piso: null, depto: null, localidad: null, provincia: null, codigoPostal: null, paisCodigo: 'AR', principal: true }) });
    return saved;
  };
  const saveMutation = useMutation({ mutationFn: async () => {
    await requestJson(`/cases/${caseId}/incident`, { method: 'PUT', body: JSON.stringify({ incidentDate: incidentQuery.data?.incidentDate ?? null, incidentTime: incident.incidentTime || null, location: incident.location || null, dynamics: incident.dynamics || null, observations: incident.observations || null }) });
    let savedVehicleId = Number(vehicle.id) || null;
    if (!savedVehicleId && vehicle.plate.trim()) savedVehicleId = (await createVehicle({ brandId: null, modelId: null, brandText: vehicle.brandText || null, modelText: vehicle.modelText || null, plate: vehicle.plate.trim(), year: null, vehicleTypeCode: 'SEDAN', usageCode: 'PARTICULAR', color: null, paintCode: null, chasis: null, motor: null, transmissionCode: null, mileage: null, observaciones: null, activo: true })).id;
    else if (savedVehicleId) await requestJson(`/vehicles/${savedVehicleId}`, { method: 'PUT', body: JSON.stringify({ ...vehicleQuery.data, plate: vehicle.plate, brandText: vehicle.brandText || null, modelText: vehicle.modelText || null }) });
    const savedDriver = driver.name.trim() ? await savePerson(driver, driverQuery.data) : null;
    const saved = await saveThirdPartyWorkshop(caseId, { thirdPartyCompanyId: workshopQuery.data?.thirdPartyCompanyId ?? null, claimReference: workshopQuery.data?.claimReference ?? null, thirdPartyVehicleId: savedVehicleId, driverPersonId: savedDriver?.id ?? (driverPersonId || null), processorPersonId: workshopQuery.data?.processor?.personId ?? null, newProcessor: null, inspectorPersonId: workshopQuery.data?.inspector?.personId ?? null, newInspector: null });
    if (driverIsOwner && savedDriver && !owners.some((owner) => String(owner.personId) === String(savedDriver.id))) await addCasePerson(caseId, { personId: savedDriver.id, caseRoleCode: 'TITULAR', vehicleId: savedVehicleId, isMain: false, notes: 'Conductor titular tercero', porcentajeTitularidad: Number(driver.ownership) || remaining });
    return saved;
  }, onSuccess: async (saved) => { queryClient.setQueryData(['cases', String(caseId), 'third-party-workshop'], saved); await Promise.all([queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'incident'] }), queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'persons'] })]); toast.success('Datos del siniestro guardados.'); }, onError: (error) => toast.error(error.message || 'No se pudieron guardar los datos del siniestro.') });
  const addOwnerMutation = useMutation({ mutationFn: async () => { const person = await savePerson(ownerDraft); return addCasePerson(caseId, { personId: person.id, caseRoleCode: 'TITULAR', vehicleId: Number(vehicle.id) || null, isMain: false, notes: 'Titular registral tercero', porcentajeTitularidad: Number(ownerDraft.ownership) }); }, onSuccess: async () => { setOwnerDraft({ ...emptyPersonDetails, ownership: String(remaining) }); setOwnerSearch(''); await queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'persons'] }); }, onError: (error) => toast.error(error.message || 'No se pudo agregar el titular.') });
  const updateOwnerMutation = useMutation({ mutationFn: async ({ owner, ownership, details }) => { await savePerson(details); return updateCasePerson(caseId, owner.id, { caseRoleCode: 'TITULAR', vehicleId: Number(vehicle.id) || null, isMain: false, notes: owner.notes ?? 'Titular registral tercero', porcentajeTitularidad: Number(ownership) }); }, onSuccess: () => queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'persons'] }) });
  const removeOwnerMutation = useMutation({ mutationFn: (relationId) => deleteCasePerson(caseId, relationId), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'persons'] }) });
  return <section className="rounded-3xl border border-border/70 bg-card p-5"><div className="flex items-center justify-between gap-3"><div><h4 className="text-sm font-semibold">Datos del siniestro</h4><p className="text-xs text-muted-foreground">Vehículo, personas involucradas y descripción del hecho.</p></div><Button size="sm" onClick={() => saveMutation.mutate()} disabled={saveMutation.isPending}><Save className="mr-1.5 h-3.5 w-3.5" />Guardar</Button></div><div className="mt-4 grid gap-3 md:grid-cols-2"><Field label="Lugar de ocurrencia"><Input aria-label="Lugar de ocurrencia" value={incident.location} onChange={(event) => setIncident((current) => ({ ...current, location: event.target.value }))} /></Field><Field label="Hora"><Input aria-label="Hora" type="time" value={incident.incidentTime} onChange={(event) => setIncident((current) => ({ ...current, incidentTime: event.target.value }))} /></Field><Field label="Dominio del tercero"><Input aria-label="Dominio del tercero" value={vehicle.plate} onChange={(event) => setVehicle((current) => ({ ...current, plate: event.target.value }))} /></Field><Field label="Marca"><Input aria-label="Marca" value={vehicle.brandText} onChange={(event) => setVehicle((current) => ({ ...current, brandText: event.target.value }))} /></Field><Field label="Modelo"><Input aria-label="Modelo" value={vehicle.modelText} onChange={(event) => setVehicle((current) => ({ ...current, modelText: event.target.value }))} /></Field><Field label="¿Es titular?"><select aria-label="¿Es titular?" value={driverIsOwner ? 'SI' : 'NO'} onChange={(event) => setDriverIsOwner(event.target.value === 'SI')} className="h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="SI">Sí</option><option value="NO">No</option></select></Field><Field label="Conductor/a del vehículo tercero" className="md:col-span-2"><PersonSummaryFields prefix="Conductor/a" value={driver} onChange={setDriver} allowOwnership={driverIsOwner} /></Field><Field label="Dinámica del siniestro" className="md:col-span-2"><Textarea aria-label="Dinámica del siniestro" value={incident.dynamics} onChange={(event) => setIncident((current) => ({ ...current, dynamics: event.target.value }))} className="min-h-20 resize-y" /></Field><Field label="Observaciones" className="md:col-span-2"><Textarea aria-label="Observaciones" value={incident.observations} onChange={(event) => setIncident((current) => ({ ...current, observations: event.target.value }))} className="min-h-20 resize-y" /></Field></div><div className="mt-5 border-t border-border/60 pt-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><h5 className="text-sm font-medium">Titular/es del vehículo tercero</h5><p className="text-xs text-muted-foreground">Total asignado: {ownershipTotal}% · Restante: {remaining}%</p></div></div>{owners.map((owner) => <OwnerRow key={owner.id} caseId={caseId} owner={owner} onSave={(ownership, details) => updateOwnerMutation.mutate({ owner, ownership, details })} onRemove={() => removeOwnerMutation.mutate(owner.id)} />)}{!driverIsOwner ? <div className="mt-3"><Input aria-label="Buscar titular" value={ownerSearch} onChange={(event) => setOwnerSearch(event.target.value)} placeholder="Buscar titular existente" />{(ownerSearchQuery.data ?? []).map((person) => <button key={person.id} type="button" className="mt-1 block text-left text-sm text-primary" onClick={() => setOwnerDraft({ personId: String(person.id), name: person.nombre ?? '', lastName: person.apellido ?? '', dni: person.numeroDocumento ?? '', address: '', ownership: String(remaining) })}>{person.nombreMostrar}</button>)}</div> : null}<div className="mt-3"><PersonSummaryFields prefix="Titular tercero" value={ownerDraft} onChange={setOwnerDraft} allowOwnership /><Button className="mt-2" size="sm" type="button" onClick={() => addOwnerMutation.mutate()} disabled={addOwnerMutation.isPending || !ownerDraft.name.trim() || remaining === 0}>Agregar tercero</Button></div></div></section>;
};

const OwnerRow = ({ owner, onSave, onRemove }) => { const personQuery = useQuery({ queryKey: ['persons', owner.personId], queryFn: () => requestJson(`/persons/${owner.personId}`) }); const [details, setDetails] = useState({ ...emptyPersonDetails, personId: String(owner.personId), ownership: String(owner.registryOwnershipPercentage ?? '') }); useEffect(() => { const person = personQuery.data; if (person?.id) setDetails((current) => ({ ...current, name: person.nombre ?? '', lastName: person.apellido ?? '', dni: person.numeroDocumento ?? '' })); }, [personQuery.data]); return <div className="mt-3 rounded-xl border border-border/60 p-3"><p className="mb-2 text-sm font-medium">{owner.displayName}</p><PersonSummaryFields prefix={`Titular ${owner.displayName}`} value={details} onChange={setDetails} allowOwnership /><div className="mt-2 flex gap-2"><Button size="sm" type="button" onClick={() => onSave(details.ownership, details)}>Guardar</Button><Button size="sm" variant="outline" type="button" onClick={onRemove}>Quitar {owner.displayName}</Button></div></div>; };

const IncidentAndInsuranceSection = ({ caseId }) => {
  const queryClient = useQueryClient();
  const incidentQuery = useQuery({ queryKey: ['cases', String(caseId), 'incident'], queryFn: () => requestJson(`/cases/${caseId}/incident`) });
  const insuranceQuery = useQuery({ queryKey: ['cases', String(caseId), 'insurance'], queryFn: () => requestJson(`/cases/${caseId}/insurance`) });
  const companiesQuery = useQuery({ queryKey: ['insurance', 'companies'], queryFn: listInsuranceCompanies });
  const [insurance, setInsurance] = useState({ insuranceCompanyId: '', claimNumber: '' });
  const [incident, setIncident] = useState({ incidentDate: '', incidentTime: '', location: '', dynamics: '', observations: '' });
  useEffect(() => { if (insuranceQuery.data) setInsurance({ insuranceCompanyId: String(insuranceQuery.data.insuranceCompanyId ?? ''), claimNumber: insuranceQuery.data.claimNumber ?? '' }); }, [insuranceQuery.data]);
  useEffect(() => { if (incidentQuery.data) setIncident({ incidentDate: incidentQuery.data.incidentDate ?? '', incidentTime: incidentQuery.data.incidentTime ?? '', location: incidentQuery.data.location ?? '', dynamics: incidentQuery.data.dynamics ?? '', observations: incidentQuery.data.observations ?? '' }); }, [incidentQuery.data]);
  const saveInsurance = useMutation({
    mutationFn: () => requestJson(`/cases/${caseId}/insurance`, { method: 'PUT', body: JSON.stringify({ insuranceCompanyId: Number(insurance.insuranceCompanyId), policyNumber: insuranceQuery.data?.policyNumber ?? null, certificateNumber: insuranceQuery.data?.certificateNumber ?? null, coverageDetail: insuranceQuery.data?.coverageDetail ?? null, claimNumber: insurance.claimNumber || null, processorPersonId: insuranceQuery.data?.processorPersonId ?? null, inspectorPersonId: insuranceQuery.data?.inspectorPersonId ?? null }) }),
    onSuccess: async () => { await queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'insurance'] }); toast.success('Seguro guardado.'); },
    onError: (error) => toast.error(error.message || 'No se pudo guardar el seguro.'),
  });
  const saveIncident = useMutation({
    mutationFn: () => requestJson(`/cases/${caseId}/incident`, { method: 'PUT', body: JSON.stringify(Object.fromEntries(Object.entries(incident).map(([key, value]) => [key, value || null]))) }),
    onSuccess: async () => { await queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'incident'] }); await queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'workspace'] }); toast.success('Siniestro guardado.'); },
    onError: (error) => toast.error(error.message || 'No se pudo guardar el siniestro.'),
  });
  return <section className="rounded-3xl border border-border/70 bg-card p-5"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-primary/10 text-primary"><Building2 className="h-5 w-5" /></div><h4 className="text-sm font-semibold">Datos del siniestro</h4></div>
    <div className="mt-5 border-t border-border/60 pt-4"><div className="flex items-center justify-between gap-3"><h5 className="text-sm font-medium">Datos del seguro</h5><Button size="sm" onClick={() => { if (!insurance.insuranceCompanyId) { toast.error('Seleccioná una compañía aseguradora.'); return; } saveInsurance.mutate(); }} disabled={saveInsurance.isPending}><Save className="mr-1.5 h-3.5 w-3.5" />Guardar seguro</Button></div><div className="mt-3 grid gap-3 md:grid-cols-2"><Field label="Cía. aseguradora"><select aria-label="Cía. aseguradora" value={insurance.insuranceCompanyId} onChange={(event) => setInsurance((current) => ({ ...current, insuranceCompanyId: event.target.value }))} className="h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Seleccionar...</option>{(companiesQuery.data ?? []).map((company) => <option key={company.id} value={company.id}>{company.name}</option>)}</select></Field><Field label="N° de siniestro"><Input value={insurance.claimNumber} onChange={(event) => setInsurance((current) => ({ ...current, claimNumber: event.target.value }))} /></Field></div></div>
    <div className="mt-5 border-t border-border/60 pt-4"><div className="flex items-center justify-between gap-3"><h5 className="text-sm font-medium">Detalle del incidente</h5><Button size="sm" onClick={() => saveIncident.mutate()} disabled={saveIncident.isPending}><Save className="mr-1.5 h-3.5 w-3.5" />Guardar siniestro</Button></div><div className="mt-3 grid gap-3 md:grid-cols-2"><Field label="Fecha del siniestro"><Input type="date" value={incident.incidentDate} onChange={(event) => setIncident((current) => ({ ...current, incidentDate: event.target.value }))} /></Field><Field label="Hora"><Input type="time" value={incident.incidentTime} onChange={(event) => setIncident((current) => ({ ...current, incidentTime: event.target.value }))} /></Field><Field label="Lugar de ocurrencia" className="md:col-span-2"><Input value={incident.location} onChange={(event) => setIncident((current) => ({ ...current, location: event.target.value }))} /></Field><Field label="Dinámica del siniestro" className="md:col-span-2"><Textarea value={incident.dynamics} onChange={(event) => setIncident((current) => ({ ...current, dynamics: event.target.value }))} className="min-h-20 resize-y" /></Field><Field label="Observaciones" className="md:col-span-2"><Textarea value={incident.observations} onChange={(event) => setIncident((current) => ({ ...current, observations: event.target.value }))} className="min-h-20 resize-y" /></Field></div></div>
  </section>;
};

const CoverageSection = ({ caseId, caseDetail, budget }) => {
  const queryClient = useQueryClient();
  const [form, setForm] = useState({ partsProvisionModeCode: '' });
  const thirdPartyQuery = useQuery({ queryKey: ['cases', String(caseId), 'third-party'], queryFn: () => getThirdParty(caseId) });
  const catalogsQuery = useQuery({ queryKey: ['insurance', 'catalogs'], queryFn: () => requestJson('/insurance/catalogs') });
  useEffect(() => { setForm({ partsProvisionModeCode: thirdPartyQuery.data?.partsProvisionModeCode ?? '' }); }, [thirdPartyQuery.data]);
  const saveMutation = useMutation({ mutationFn: () => saveThirdParty(caseId, { thirdPartyCompanyId: thirdPartyQuery.data?.thirdPartyCompanyId ?? null, claimReference: thirdPartyQuery.data?.claimReference ?? null, partsProvisionModeCode: form.partsProvisionModeCode || null }), onSuccess: async (saved) => { queryClient.setQueryData(['cases', String(caseId), 'third-party'], saved); await queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'workspace'] }); toast.success('Datos de cobertura guardados.'); }, onError: (error) => toast.error(error.message || 'No se pudo guardar la cobertura.') });
  const modes = (catalogsQuery.data?.partsProvisionModeCodes ?? []).filter((item) => caseDetail?.caseTypeCode !== 'RECLAMO_TERCEROS' || ['COMPANIA', 'TALLER', 'CLIENTE'].includes(item.code));
  const data = thirdPartyQuery.data;
  return <section className="rounded-3xl border border-border/70 bg-card p-5"><div className="flex items-center justify-between gap-3"><div><h4 className="text-sm font-semibold">Datos de cobertura y acuerdo</h4><p className="text-xs text-muted-foreground">Valores calculados a partir del presupuesto y el acuerdo.</p></div><Button size="sm" onClick={() => saveMutation.mutate()} disabled={saveMutation.isPending}><Save className="mr-1.5 h-3.5 w-3.5" />Guardar</Button></div><div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3"><Field label="Provee repuestos"><select aria-label="Provee repuestos" value={form.partsProvisionModeCode} onChange={(event) => setForm({ partsProvisionModeCode: event.target.value })} className="h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Seleccionar...</option>{modes.map((item) => <option key={item.code} value={item.code}>{item.name}</option>)}</select></Field><CalculatedField label="Mínimo mano de obra" value={data?.minimumLaborAmount} fallback="Se calcula desde Presupuesto" />{data?.includesParts ? <><CalculatedField label="Mínimo repuestos" value={data?.minimumPartsAmount} fallback="Se calcula desde cotizaciones" /><CalculatedField label="Subtotal mejor cotización" value={data?.bestQuotationSubtotal} fallback="Se calcula desde cotizaciones" /></> : null}{form.partsProvisionModeCode === 'TALLER' ? <CalculatedField label="Total final repuestos" value={data?.finalPartsTotal} fallback="Se calcula desde pedidos" /> : null}<CalculatedField label="A facturar compañía" value={data?.amountToBillCompany} fallback="Se calcula desde el acuerdo" /><CalculatedField label="Final a favor taller" value={data?.finalAmountForWorkshop} fallback="Se calcula al guardar" /></div>{budget ? <p className="mt-3 text-xs text-muted-foreground">El presupuesto cerrado y los pedidos determinan los mínimos y los repuestos definitivos.</p> : null}</section>;
};

const CalculatedField = ({ label, value, fallback }) => <Field label={label}><Input readOnly value={value == null || value === '' ? fallback : value} className="cursor-not-allowed bg-muted/50" /></Field>;

const ContactControl = ({ label, companyId, roleCode, personId, savedContact, onPersonChange, newContact, onNewContactChange }) => {
  const [creating, setCreating] = useState(false);
  const contactsQuery = useQuery({ queryKey: ['insurance', 'companies', companyId, 'contacts'], queryFn: () => listInsuranceCompanyContacts(companyId), enabled: Boolean(companyId) });
  const personQuery = useQuery({ queryKey: ['persons', personId], queryFn: () => requestJson(`/persons/${personId}`), enabled: Boolean(personId) });
  const contacts = (contactsQuery.data ?? []).filter((contact) => contact.contactRoleCode === roleCode);
  const selected = savedContact?.personId === Number(personId) ? savedContact : personQuery.data;
  if (!companyId) return <Field label={label}><p className="py-2 text-sm font-normal normal-case text-muted-foreground">Seleccioná la compañía del tercero.</p></Field>;
  return <Field label={label}><select aria-label={label} value={creating ? '__new' : personId} onChange={(event) => { if (event.target.value === '__new') { setCreating(true); onPersonChange(''); } else { setCreating(false); onPersonChange(event.target.value); } }} className="h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Seleccionar...</option>{contacts.map((contact) => <option key={contact.id} value={contact.personId}>{contact.personName}</option>)}<option value="__new">Crear contacto...</option></select>{creating ? <div className="mt-2 grid gap-2 md:grid-cols-3"><Input aria-label={`Nombre ${label}`} value={newContact.name} onChange={(event) => onNewContactChange({ ...newContact, name: event.target.value })} placeholder="Nombre completo" /><Input aria-label={`Correo ${label}`} value={newContact.email} onChange={(event) => onNewContactChange({ ...newContact, email: event.target.value })} placeholder="correo@compania.com" /><Input aria-label={`Teléfono ${label}`} value={newContact.phone} onChange={(event) => onNewContactChange({ ...newContact, phone: event.target.value })} placeholder="Teléfono" /></div> : selected ? <p className="mt-2 text-sm font-normal normal-case text-muted-foreground">{selected.name || personName(selected)} · {selected.email || selected.emailPrincipal || 'Sin correo'} · {selected.phone || selected.telefonoPrincipal || 'Sin teléfono'}</p> : null}</Field>;
};

const InvolvedThirdPartiesSection = ({ caseId }) => {
  const queryClient = useQueryClient();
  const workshopQuery = useQuery({ queryKey: ['cases', String(caseId), 'third-party-workshop'], queryFn: () => getThirdPartyWorkshop(caseId) });
  const casePersonsQuery = useQuery({ queryKey: ['cases', String(caseId), 'persons'], queryFn: () => getCasePersons(caseId) });
  const companiesQuery = useQuery({ queryKey: ['insurance', 'companies'], queryFn: listInsuranceCompanies });
  const [workshop, setWorkshop] = useState(emptyWorkshop);
  const [vehicle, setVehicle] = useState(emptyVehicle);
  const [processor, setProcessor] = useState(emptyContact);
  const [inspector, setInspector] = useState(emptyContact);
  const [driverSearch, setDriverSearch] = useState(''); const [driverName, setDriverName] = useState(''); const [creatingDriver, setCreatingDriver] = useState(false);
  const [ownerSearch, setOwnerSearch] = useState(''); const [ownerPersonId, setOwnerPersonId] = useState(''); const [ownership, setOwnership] = useState('100');
  useEffect(() => { const data = workshopQuery.data; if (!data) return; setWorkshop({ thirdPartyCompanyId: String(data.thirdPartyCompanyId ?? ''), claimReference: data.claimReference ?? '', thirdPartyVehicleId: String(data.thirdPartyVehicleId ?? ''), driverPersonId: String(data.driverPersonId ?? ''), processorPersonId: String(data.processor?.personId ?? ''), inspectorPersonId: String(data.inspector?.personId ?? '') }); }, [workshopQuery.data]);
  const driverPeopleQuery = useQuery({ queryKey: ['persons', 'third-party-driver', driverSearch], queryFn: () => searchPersons({ q: driverSearch }), enabled: driverSearch.trim().length >= 2 });
  const ownerPeopleQuery = useQuery({ queryKey: ['persons', 'third-party-owner', ownerSearch], queryFn: () => searchPersons({ q: ownerSearch }), enabled: ownerSearch.trim().length >= 2 });
  const vehicleSearchQuery = useQuery({ queryKey: ['vehicles', 'third-party', vehicle.search], queryFn: () => searchVehicles({ q: vehicle.search }), enabled: vehicle.search.trim().length >= 2 });
  const selectedVehicleId = Number(workshop.thirdPartyVehicleId) || null;
  const owners = (casePersonsQuery.data ?? []).filter((person) => person.caseRoleCode === 'TITULAR' && person.vehicleId === selectedVehicleId);
  const ownershipTotal = owners.reduce((total, owner) => total + Number(owner.registryOwnershipPercentage || 0), 0);
  const remaining = 100 - ownershipTotal; const requested = Number(ownership) || 0;
  const ownerAlreadyLinked = owners.some((owner) => String(owner.personId) === ownerPersonId);
  const saveMutation = useMutation({ mutationFn: async () => { let thirdPartyVehicleId = selectedVehicleId; if (!thirdPartyVehicleId && vehicle.plate.trim()) { thirdPartyVehicleId = (await createVehicle({ brandId: null, modelId: null, brandText: vehicle.brandText || null, modelText: vehicle.modelText || null, plate: vehicle.plate.trim(), year: null, vehicleTypeCode: 'SEDAN', usageCode: 'PARTICULAR', color: null, paintCode: null, chasis: null, motor: null, transmissionCode: null, mileage: null, observaciones: null, activo: true })).id; } if (!thirdPartyVehicleId && (vehicle.brandText || vehicle.modelText)) throw new Error('Indicá el dominio para crear el vehículo del tercero.'); return saveThirdPartyWorkshop(caseId, { thirdPartyCompanyId: workshop.thirdPartyCompanyId ? Number(workshop.thirdPartyCompanyId) : null, claimReference: workshop.claimReference || null, thirdPartyVehicleId, driverPersonId: workshop.driverPersonId ? Number(workshop.driverPersonId) : null, processorPersonId: workshop.processorPersonId ? Number(workshop.processorPersonId) : null, newProcessor: !workshop.processorPersonId && processor.name.trim() ? { name: processor.name.trim(), email: processor.email || null, phone: processor.phone || null } : null, inspectorPersonId: workshop.inspectorPersonId ? Number(workshop.inspectorPersonId) : null, newInspector: !workshop.inspectorPersonId && inspector.name.trim() ? { name: inspector.name.trim(), email: inspector.email || null, phone: inspector.phone || null } : null }); }, onSuccess: async (saved) => { queryClient.setQueryData(['cases', String(caseId), 'third-party-workshop'], saved); await queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'persons'] }); toast.success('Terceros involucrados guardados.'); }, onError: (error) => toast.error(error.message || 'No se pudieron guardar los terceros.') });
  const createDriverMutation = useMutation({ mutationFn: () => createPerson({ tipoPersona: 'fisica', nombre: driverName.trim(), apellido: '', activo: true }), onSuccess: (person) => { setWorkshop((current) => ({ ...current, driverPersonId: String(person.id) })); setDriverSearch(personName(person)); setCreatingDriver(false); setDriverName(''); toast.success('Conductor creado.'); }, onError: (error) => toast.error(error.message || 'No se pudo crear el conductor.') });
  const addOwnerMutation = useMutation({ mutationFn: () => addCasePerson(caseId, { personId: Number(ownerPersonId), caseRoleCode: 'TITULAR', vehicleId: selectedVehicleId, isMain: false, notes: 'Titular registral tercero', porcentajeTitularidad: requested }), onSuccess: async () => { await queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'persons'] }); setOwnerPersonId(''); setOwnerSearch(''); setOwnership(String(Math.max(0, remaining - requested))); toast.success('Titular del tercero incorporado.'); }, onError: (error) => toast.error(error.message || 'No se pudo incorporar el titular.') });
  const updateOwnerMutation = useMutation({ mutationFn: ({ owner, percentage }) => updateCasePerson(caseId, owner.id, { caseRoleCode: 'TITULAR', vehicleId: selectedVehicleId, isMain: false, notes: owner.notes, porcentajeTitularidad: percentage }), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'persons'] }), onError: (error) => toast.error(error.message || 'No se pudo actualizar la titularidad.') });
  const removeOwnerMutation = useMutation({ mutationFn: (relationId) => deleteCasePerson(caseId, relationId), onSuccess: async () => { await queryClient.invalidateQueries({ queryKey: ['cases', String(caseId), 'persons'] }); toast.success('Titular del tercero quitado.'); }, onError: (error) => toast.error(error.message || 'No se pudo quitar el titular.') });
  const createOwnerMutation = useMutation({ mutationFn: () => createPerson({ tipoPersona: 'fisica', nombre: ownerSearch.trim(), apellido: '', activo: true }), onSuccess: (person) => { setOwnerPersonId(String(person.id)); setOwnerSearch(personName(person)); toast.success('Persona creada.'); }, onError: (error) => toast.error(error.message || 'No se pudo crear la persona.') });
  return <section className="rounded-3xl border border-border/70 bg-card p-5"><div className="flex items-center justify-between gap-3"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-primary/10 text-primary"><UserRound className="h-5 w-5" /></div><div><h4 className="text-sm font-semibold">Terceros involucrados</h4><p className="text-xs text-muted-foreground">Compañía, contactos, vehículo, conductor y titulares del tercero.</p></div></div><Button size="sm" onClick={() => saveMutation.mutate()} disabled={saveMutation.isPending}><Save className="mr-1.5 h-3.5 w-3.5" />Guardar</Button></div><div className="mt-4 grid gap-3 md:grid-cols-2"><Field label="Compañía del tercero"><select aria-label="Compañía del tercero" value={workshop.thirdPartyCompanyId} onChange={(event) => setWorkshop((current) => ({ ...current, thirdPartyCompanyId: event.target.value, processorPersonId: '', inspectorPersonId: '' }))} className="h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Seleccionar...</option>{(companiesQuery.data ?? []).map((company) => <option key={company.id} value={company.id}>{company.name}</option>)}</select></Field><Field label="Referencia de reclamo"><Input value={workshop.claimReference} onChange={(event) => setWorkshop((current) => ({ ...current, claimReference: event.target.value }))} /></Field><ContactControl label="Tramitador/a" companyId={workshop.thirdPartyCompanyId} roleCode="TRAMITADOR" personId={workshop.processorPersonId} savedContact={workshopQuery.data?.processor} onPersonChange={(processorPersonId) => setWorkshop((current) => ({ ...current, processorPersonId }))} newContact={processor} onNewContactChange={setProcessor} /><ContactControl label="Inspector/a" companyId={workshop.thirdPartyCompanyId} roleCode="INSPECTOR" personId={workshop.inspectorPersonId} savedContact={workshopQuery.data?.inspector} onPersonChange={(inspectorPersonId) => setWorkshop((current) => ({ ...current, inspectorPersonId }))} newContact={inspector} onNewContactChange={setInspector} /></div><div className="mt-5 border-t border-border/60 pt-4"><div className="flex items-center gap-2"><Car className="h-4 w-4 text-primary" /><h5 className="text-sm font-medium">Vehículo y conductor del tercero</h5></div><div className="mt-3 grid gap-3 md:grid-cols-2"><Field label="Buscar vehículo"><Input value={vehicle.search} onChange={(event) => setVehicle((current) => ({ ...current, search: event.target.value }))} placeholder="Dominio, marca o modelo" />{(vehicleSearchQuery.data ?? []).map((item) => <button key={item.id} type="button" className="mt-1 block text-left text-sm text-primary" onClick={() => { setWorkshop((current) => ({ ...current, thirdPartyVehicleId: String(item.id) })); setVehicle({ search: `${item.plate || ''} ${item.brandText || ''} ${item.modelText || ''}`.trim(), brandText: '', modelText: '', plate: '' }); }}>{[item.plate, item.brandText, item.modelText].filter(Boolean).join(' · ')}</button>)}</Field><Field label="Dominio"><Input value={vehicle.plate} onChange={(event) => setVehicle((current) => ({ ...current, plate: event.target.value }))} placeholder="Para crear un vehículo nuevo" /></Field><Field label="Marca"><Input value={vehicle.brandText} onChange={(event) => setVehicle((current) => ({ ...current, brandText: event.target.value }))} /></Field><Field label="Modelo"><Input value={vehicle.modelText} onChange={(event) => setVehicle((current) => ({ ...current, modelText: event.target.value }))} /></Field><Field label="Conductor/a" className="md:col-span-2"><Input value={driverSearch} onChange={(event) => { setDriverSearch(event.target.value); setWorkshop((current) => ({ ...current, driverPersonId: '' })); }} placeholder="Buscar conductor por nombre o documento" />{(driverPeopleQuery.data ?? []).map((person) => <button key={person.id} type="button" className="mt-1 mr-3 text-sm text-primary" onClick={() => { setWorkshop((current) => ({ ...current, driverPersonId: String(person.id) })); setDriverSearch(personName(person)); }}>{personName(person)}</button>)}<Button type="button" size="sm" variant="outline" className="mt-2" onClick={() => setCreatingDriver(true)}>Crear conductor</Button>{creatingDriver ? <div className="mt-2 flex gap-2"><Input aria-label="Nombre nuevo conductor" value={driverName} onChange={(event) => setDriverName(event.target.value)} placeholder="Nombre completo" /><Button type="button" size="sm" onClick={() => createDriverMutation.mutate()} disabled={!driverName.trim() || createDriverMutation.isPending}>Crear</Button></div> : null}</Field></div></div><div className="mt-5 border-t border-border/60 pt-4"><h5 className="text-sm font-medium">Titulares registrales del tercero</h5>{selectedVehicleId ? <><p className="mt-1 text-xs text-muted-foreground">Titularidad registrada: {ownershipTotal}% · Restante: {remaining}%.</p><div className="mt-3 grid gap-3 md:grid-cols-[1fr_130px_auto]"><div><Input value={ownerSearch} onChange={(event) => { setOwnerSearch(event.target.value); setOwnerPersonId(''); }} placeholder="Buscar titular por nombre o documento" />{(ownerPeopleQuery.data ?? []).map((person) => <button key={person.id} type="button" className="mt-1 mr-3 text-sm text-primary" onClick={() => { setOwnerPersonId(String(person.id)); setOwnerSearch(personName(person)); }}>{personName(person)}</button>)}<Button type="button" size="sm" variant="outline" className="mt-2 mr-2" onClick={() => createOwnerMutation.mutate()} disabled={!ownerSearch.trim() || createOwnerMutation.isPending}>Crear titular</Button>{workshop.driverPersonId ? <Button type="button" size="sm" variant="outline" className="mt-2" onClick={() => { setOwnerPersonId(workshop.driverPersonId); setOwnerSearch(driverSearch || 'Conductor seleccionado'); }}>Usar conductor como titular</Button> : null}</div><Input aria-label="Porcentaje titular tercero" type="number" min="1" max={remaining} value={ownership} onChange={(event) => setOwnership(event.target.value)} /><Button type="button" size="sm" onClick={() => addOwnerMutation.mutate()} disabled={!ownerPersonId || ownerAlreadyLinked || requested < 1 || requested > remaining || addOwnerMutation.isPending}>Agregar titular</Button></div>{requested > remaining ? <p className="mt-2 text-xs text-destructive">Supera el 100% acumulado.</p> : null}<ul className="mt-3 space-y-2">{owners.map((owner) => <li key={owner.id} className="flex items-center gap-3 text-sm"><span className="min-w-40">{owner.displayName}</span><Input aria-label={`Porcentaje de ${owner.displayName}`} type="number" min="1" max={remaining + Number(owner.registryOwnershipPercentage || 0)} defaultValue={owner.registryOwnershipPercentage} onBlur={(event) => { const percentage = Number(event.target.value) || 0; const maximum = remaining + Number(owner.registryOwnershipPercentage || 0); if (percentage >= 1 && percentage <= maximum) updateOwnerMutation.mutate({ owner, percentage }); }} /><Button type="button" size="sm" variant="ghost" className="text-destructive" aria-label={`Quitar ${owner.displayName}`} onClick={() => removeOwnerMutation.mutate(owner.id)} disabled={removeOwnerMutation.isPending}>Quitar</Button></li>)}</ul></> : <p className="mt-2 text-sm text-muted-foreground">Guardá o seleccioná primero el vehículo del tercero para asignar titulares.</p>}</div></section>;
};
